# -*- coding: utf-8 -*-
# 批注数据：src/commands/insights.ts（3200 行，/insights 命令：会话用量分析 → 结构化维度 → HTML 报告）
# slug = src_commands_insights_ts
ANNOTATIONS = [
    (39, 'after', r'''文件级：/insights 命令的核心实现。它扫描本机（以及 ant 内部环境可选的远程 homespace）的 Claude Code 会话日志，抽取结构化维度 facets，聚合统计指标，调用 Opus 生成叙事性洞察，最后渲染成一份自包含的 HTML 报告。整份文件可分成四段：数据采集、类型与常量、统计与洞察生成、HTML 渲染与主流程。'''),
    (43, 'after', r'''getAnalysisModel：facet 抽取与段落摘要阶段使用的模型——固定取默认 Opus，用质量换速度，因为这两步对文本理解要求最高。'''),
    (48, 'after', r'''getInsightsModel：叙事洞察阶段同样用默认 Opus，保证生成洞察的语言质量。'''),
    (52, 'after', r'''段：Homespace 数据采集（仅 ant 内部环境生效）。当 USER_TYPE 为 ant 时，从远程 coder workspaces 拉取会话合并进本地用于分析；非 ant 环境下这些函数一律返回空，逻辑被编译期条件剪掉。'''),
    (57, 'after', r'''RemoteHostInfo：远程主机元信息类型，只记录主机名与它的会话数。'''),
    (81, 'after', r'''getRunningRemoteHosts：ant 环境下用 coder list 列出正在运行的工作区；失败或非 ant 环境返回空数组。'''),
    (97, 'after', r'''getRemoteHostSessionCount：对单台 homespace 通过 ssh 统计其 /root/.claude/projects 下的 jsonl 会话数；非 ant 返回 0。'''),
    (184, 'after', r'''collectFromRemoteHost：把单台 homespace 的 projects 目录 scp 到本地临时目录，再按项目合并进目标目录，已存在的文件用 COPYFILE_EXCL 跳过（绝不覆盖本地数据）。'''),
    (221, 'after', r'''collectAllRemoteHostData：并发拉取所有运行中的 homespace，汇总主机列表与复制/跳过计数，供主流程决定是否纳入分析。'''),
    (226, 'after', r'''段：类型定义。下面三组数据结构是整份文件的「数据契约」——SessionMeta 描述单会话指标、SessionFacets 是模型抽取的结构化维度、AggregatedData 是跨会话聚合结果。'''),
    (258, 'after', r'''SessionMeta：单条会话的扁平指标——时长、消息数、工具调用计数、语言分布、git 提交/推送、token 消耗、用户中断次数、响应时间数组、工具错误分类，以及文件改动的行数与文件数（用于衡量真实产出）。'''),
    (273, 'after', r'''SessionFacets：由 Opus 从会话中抽取的结构化维度——底层目标、目标类别计数、结果、满意度、帮助度、会话类型、摩擦点及一句话摘要；这是整份分析的「语义层」。'''),
    (326, 'after', r'''AggregatedData：跨所有会话的聚合结果——各类总量、按类别的分布表，以及中位数/平均响应时间、多开（multi-clauding）统计等派生指标。'''),
    (330, 'after', r'''段：常量。EXTENSION_TO_LANGUAGE 与 LABEL_MAP 负责把代码里的原始键翻译成人类可读标签与语言名。'''),
    (349, 'after', r'''EXTENSION_TO_LANGUAGE：文件扩展名到编程语言的映射，用于统计用户究竟改了哪些语言。'''),
    (415, 'after', r'''LABEL_MAP：把 snake_case 类别键翻译成展示标签（如 debug_investigate → Debug/Investigate），覆盖目标/成功/摩擦/满意度/会话类型/结果/帮助度共七类。'''),
    (428, 'after', r'''getDataDir / getFacetsDir / getSessionMetaDir：三个懒加载目录获取器，拼接 usage-data 下的子目录；刻意不放在模块顶层，避免提前固化 config 目录而破坏其他 150+ 调用方。'''),
    (457, 'after', r'''FACET_EXTRACTION_PROMPT：指导模型只数「用户明确要求的」目标类别（不算 Claude 自主探索），并区分满意度/摩擦的判定标准，最终只回 JSON，减少后续解析麻烦。'''),
    (465, 'after', r'''getLanguageFromPath：按扩展名查表得到语言名，查不到返回 null。'''),
    (467, 'before', r'''extractToolStats：核心统计函数，逐条遍历会话消息，提取工具/语言/git/token/错误等指标，是后面所有聚合的数据来源。'''),
    (728, 'after', r'''extractToolStats 收尾：返回的统计对象含工具计数、语言分布、git 提交/推送、token、中断与响应时间、工具错误分类、是否用过 task agent / mcp / web，以及文件改动行数与修改集合；只把带真实文本的用户消息计入响应时间，过滤掉纯 tool_result。'''),
    (735, 'after', r'''hasValidDates：检查会话的创建/修改时间是否都是合法日期，过滤掉损坏日志。'''),
    (801, 'after', r'''logToSessionMeta：把一条 LogOption 转成扁平的 SessionMeta——先 extractToolStats 拿指标，再统计人类消息数，最后组装成结构化记录。'''),
    (829, 'after', r'''deduplicateSessionBranches：同一会话文件可能有多个叶子分支（重试/分叉），这里按 session_id 去重，只保留用户消息最多（并列时取时长最长）的那条分支，避免重复计数拉高总量。'''),
    (868, 'after', r'''formatTranscriptForFacets：把会话转成给模型看的纯文本摘要——逐条消息摘出 [User]/[Assistant]/[Tool] 片段，用户消息截前 500 字、助手截前 300 字，控制 tokens。'''),
    (879, 'after', r'''SUMMARIZE_CHUNK_PROMPT：长会话的段落摘要提示词，要求用 3-5 句浓缩用户诉求、Claude 动作、摩擦与结果，并保留文件名/报错等具体细节。'''),
    (904, 'after', r'''summarizeTranscriptChunk：调用模型对单个段落摘要；失败就退回原始片段前 2000 字，保证流程不中断。'''),
    (939, 'after', r'''formatTranscriptWithSummarization：超过 3 万字符的会话切成 2.5 万字符的块并行摘要，再拼回带头部的总摘要，避免超长上下文把模型撑爆。'''),
    (961, 'after', r'''loadCachedFacets：读本地 facets 缓存；结构校验失败就删掉损坏文件，让下次重新抽取，而不是带着脏数据继续。'''),
    (974, 'after', r'''saveFacets：把 facets 写入 usage-data/facets/<sessionId>.json，权限设为仅本人可读（0o600），避免用量数据泄露。'''),
    (999, 'after', r'''loadCachedSessionMeta / saveSessionMeta：与 facets 对称的 SessionMeta 缓存读写，同样以 0o600 落盘，命中缓存就能跳过昂贵的 jsonl 解析。'''),
    (1055, 'after', r'''extractFacetsFromAPI：对单条会话调用 Opus 抽取 facets——长会话先摘要，再要求模型只回 JSON，解析失败或校验不过返回 null 并记错误日志（单条失败不影响整体）。'''),
    (1143, 'after', r'''detectMultiClauding：用 30 分钟滑动窗口检测「多开」——若在窗口内出现 s1→s2→s1 的会话交错，记为一次重叠事件；统计重叠事件数、涉及会话数、期间用户消息数，反映并行工作习惯。'''),
    (1323, 'after', r'''aggregateData：把所有 SessionMeta + facets 汇总成 AggregatedData——累加总量、按类别聚合分布、算中位数/平均响应时间、活跃天数与日均消息，并调用 detectMultiClauding 补多开统计。'''),
    (1327, 'after', r'''段：并行洞察生成（6 个固定 section）。INSIGHT_SECTIONS 定义了要并发生成的板块（项目领域/交互风格/成效/摩擦/建议/未来机会等），每个板块各自带 JSON schema 提示词。'''),
    (1495, 'after', r'''INSIGHT_SECTIONS 数组结束：ant 环境会额外注入 cc_team_improvements 与 model_behavior_improvements 两个板块，给内部团队产出产品/模型改进建议。'''),
    (1570, 'after', r'''InsightResults：六个板块各自的返回结构定义，全部字段可选，因为任一板块抽取失败都可能为空，渲染时要做空值保护。'''),
    (1610, 'after', r'''generateSectionInsight：单板块洞察生成器——调模型、从回复里抠 JSON、解析失败记日志并返回 null，做到「单板块出错不影响其他板块」。'''),
    (1798, 'after', r'''generateParallelInsights：先并发跑 INSIGHT_SECTIONS 各板块，再把产出拼成「At a Glance」所需的富上下文，最后单独生成 4 段式 At a Glance 摘要；前序板块的失败只会让对应字段缺失。'''),
    (1804, 'after', r'''escapeHtmlWithBold：HTML 转义后把 **bold** 标记替换成 <strong>，用于把模型 Markdown 加粗渲染成网页加粗。'''),
    (1822, 'after', r'''SATISFACTION_ORDER / OUTCOME_ORDER：图表固定排序数组，保证满意度（沮丧→开心）与结果（未达成→完全达成）在柱状图里顺序恒定、可读，不随数据随机抖动。'''),
    (1861, 'after', r'''generateBarChart：通用横向柱状图生成器——支持固定顺序（用 LABEL_MAP 或传入 fixedOrder）或按计数降序，最多显示 maxItems 条；无数据返回空提示。'''),
    (1900, 'after', r'''generateResponseTimeHistogram：把用户响应时间分桶（2-10s 到 >15m）画成柱状图，直观展示「用户思考/等待时长」的分布。'''),
    (1937, 'after', r'''generateTimeOfDayChart：把消息按一天四个时段（早/午/晚/夜）聚合，前端可切换时区动态重算分布。'''),
    (1945, 'after', r'''getHourCountsJson：把每小时消息数序列化成 JSON，供前端时区切换时动态重建时段柱状图，无需后端重算。'''),
    (2646, 'after', r'''generateHtmlReport：整份报告的总装函数——把各个洞察板块拼成带导航目录、统计行、图表和卡片的自包含 HTML，内联 CSS 与 JS（含时区切换、复制按钮、折叠面板），返回完整文档字符串。'''),
    (2673, 'after', r'''InsightsExport：给 claudescope（外部消费方）的结构化导出类型——含 metadata、聚合数据、洞察与 facets 摘要，方便别的服务二次利用。'''),
    (2737, 'after', r'''buildExportData：用已算好的聚合数据/洞察/facets 组装 InsightsExport；版本号取自 MACRO.VERSION，远程主机只列有会话的，避免导出空壳。'''),
    (2741, 'after', r'''段：轻量会话扫描。scanAllSessions 只读文件系统元数据（mtime/size），不解析 jsonl，按 mtime 倒序返回会话清单，每 10 个工程目录让出一次事件循环保持 UI 响应。'''),
    (2794, 'after', r'''段：主流程。generateUsageReport 是命令入口，分四阶段跑完整个分析流水线，最后把 HTML 写到 usage-data/report.html。'''),
    (2815, 'after', r'''阶段一（Lite 扫描）：scanAllSessions 只扫元数据，拿到全量会话清单与总数，几乎零成本，先建立「有多少会话」的全局视图。'''),
    (2840, 'after', r'''阶段二（加载 SessionMeta）：以 50 个一批并发读缓存，命中即用，未命中且未超 200 上限的进入待解析队列，避免对老会话重复解析。'''),
    (2890, 'after', r'''阶段二续：以 10 个一批加载未缓存会话的 jsonl，转成 SessionMeta 并落盘缓存；同时过滤掉 /insights 自身的元会话与无合法日期的损坏日志。'''),
    (2925, 'after', r'''isSubstantiveSession：预过滤掉用户消息少于 2 或时长不足 1 分钟的极简会话，省下后续昂贵的 API 调用。'''),
    (2981, 'after', r'''isMinimalSession：若某会话唯一的目标类别只是 warmup_minimal（缓存预热），视为无意义会话剔除，匹配 Python 参考的 is_minimal 逻辑。'''),
    (2992, 'after', r'''实质性筛选：用 isMinimalSession 同时过滤 sessions 与 facets，保证聚合与洞察只基于「真有意义」的会话。'''),
    (3023, 'after', r'''generateUsageReport 收尾：聚合 → 并行洞察 → 生成 HTML → 写入 usage-data/report.html，返回洞察、路径、聚合数据与 facets 供命令层使用。'''),
    (3033, 'after', r'''safeEntries / safeKeys：对可能为空的对象做 Object.entries/keys 的安全封装，空时返回空数组，避免下游解构或遍历报错。'''),
    (3037, 'after', r'''段：命令定义。usageReport 是 /insights 命令的本体，type 为 prompt，由 getPromptForCommand 在运行时拼出给模型的提示词。'''),
    (3066, 'after', r'''getPromptForCommand 开头：ant 环境解析 --homespaces 标志、检查可用远程主机，并在收集时打印进度提示，让内部用户知道正在拉取。'''),
    (3100, 'after', r'''ant 上传分支：把报告用内部 ff cp 传到 S3，失败则降级为本地 file:// 并提示用 use-bo / sso 重试，保证命令总有可用输出。'''),
    (3182, 'after', r'''getPromptForCommand 返回：把完整洞察 JSON、报告 URL、HTML 路径拼进提示词，要求模型原样输出一段「报告已就绪」消息；这是命令对外的最终交付。'''),
    (3198, 'after', r'''isValidSessionFacets：facets 缓存的结构守卫——要求 underlying_goal/outcome/brief_summary 为字符串且各计数对象非空，校验不过的缓存会被删除重抽。'''),
    (3200, 'after', r'''默认导出 usageReport，注册为 /insights 命令，供 CLI 调用。'''),
]
